import{_ as p,a0 as d,w as o,s as b,I as t,x as e,a1 as n,A as l,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Ubuntu Linux 上安裝 Deb 文件的 3 種方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu Linux 上安裝 Deb 文件的 3 種方法 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu Linux 上安裝 Deb 文件的 3 種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu Linux 上安裝 Deb 文件的 3 種方法 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20190208 3 Ways to Install Deb Files on Ubuntu Linux","title":"在 Ubuntu Linux 上安裝 Deb 文件的 3 種方法","tag":"202012","desc":""},"relativePath":"202012/20190208 3 Ways to Install Deb Files on Ubuntu Linux.md","filePath":"[post].md"}'),u={name:"202012/20190208 3 Ways to Install Deb Files on Ubuntu Linux.md"};function r(g,s,k,h,f,m){const i=d("Link");return o(),b("div",null,[s[38]||(s[38]=t("h1",{id:"在-ubuntu-linux-上安裝-deb-文件的-3-種方法",tabindex:"-1"},[e("在 Ubuntu Linux 上安裝 Deb 文件的 3 種方法 "),t("a",{class:"header-anchor",href:"#在-ubuntu-linux-上安裝-deb-文件的-3-種方法","aria-label":"Permalink to “在 Ubuntu Linux 上安裝 Deb 文件的 3 種方法”"},"​")],-1)),s[39]||(s[39]=t("blockquote",null,[t("p",null,"這篇初學者文章解釋瞭如何在 Ubuntu 中安裝 deb 軟件包。它稍後也向你展示如何移除這些 deb 軟件包。")],-1)),t("p",null,[s[1]||(s[1]=e("這是 Ubuntu 初學者系列的另一篇文章。如果你對 Ubuntu 很陌生，你可能會想知道 ",-1)),n(i,{href:"https://itsfoss.com/remove-install-software-ubuntu/"},{default:l(()=>[...s[0]||(s[0]=[e("如何安裝應用程序",-1)])]),_:1}),s[2]||(s[2]=e("。",-1))]),s[40]||(s[40]=t("p",null,"最簡單的方法是使用 Ubuntu 軟件中心。在軟件中心中搜索應用程序的名稱並安裝它。如果你能在軟件中心中找到所有的應用程序，那麼生活就太愜意了。但是，不幸的是，這是不可能的發生的。",-1)),s[41]||(s[41]=t("p",null,"一些軟件包可以通過 DEB 軟件包的形式獲得。它們是以 .deb 擴展名為結尾的存檔文件。你可以把 .deb 文件看作為 Windows 中的 .exe 文件。在 Windows 中，你雙擊 .exe 文件，它將開始安裝過程。DEB 軟件包也是非常類似的。",-1)),t("p",null,[s[4]||(s[4]=e("你可以從軟件提供商網站的下載區域找到這些 DEB 軟件包。例如，如果你想 ",-1)),n(i,{href:"https://itsfoss.com/install-chrome-ubuntu/"},{default:l(()=>[...s[3]||(s[3]=[e("在 Ubuntu 上安裝 Google Chrome",-1)])]),_:1}),s[5]||(s[5]=e(" ，你可以從它的網站下載 Chrome 的 DEB 軟件包。",-1))]),s[42]||(s[42]=a('<p>現在問題產生了，你將如何安裝 deb 文件呢？在 Ubuntu 中有多種安裝 DEB 軟件包的方法。在這篇教程中，我將向你依次地展示它們。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/02/deb-packages-ubuntu.png?resize=800%2C450&amp;ssl=1" alt="在 Ubuntu 中安裝 deb 文件"></p><h3 id="在-ubuntu-和基於-debian-的-linux-發行版中安裝-deb-文件" tabindex="-1">在 Ubuntu 和基於 Debian 的 Linux 發行版中安裝 .deb 文件 <a class="header-anchor" href="#在-ubuntu-和基於-debian-的-linux-發行版中安裝-deb-文件" aria-label="Permalink to “在 Ubuntu 和基於 Debian 的 Linux 發行版中安裝 .deb 文件”">​</a></h3><p>你可以選擇一個 GUI 工具或一個命令列工具來安裝一個 deb 軟件包。你擁有選擇權。</p><p>讓我們繼續看看如何安裝 deb 文件。</p><h4 id="方法-1-使用默認的軟件中心" tabindex="-1">方法 1: 使用默認的軟件中心 <a class="header-anchor" href="#方法-1-使用默認的軟件中心" aria-label="Permalink to “方法 1: 使用默認的軟件中心”">​</a></h4><p>在 Ubuntu 中，最簡單的方法是使用默認的軟件中心。在這裏你不必要做任何特別的事。只需要轉到你所下載的 .deb 文件的文件夾下（它應該是 Downloads 文件夾），並在這個文件上雙擊。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/01/install-google-chrome-ubuntu-4.jpeg?resize=800%2C347&amp;ssl=1" alt="在 Ubuntu 上的 Google Chrome 的 deb 文件"></p><p>在已下載的 .deb 文件上雙擊以開始安裝。</p><p>它將打開軟件中心，並且你將看到安裝軟件時的選項。你所需要做的全部工作就是：點擊安裝按鈕並輸入你的登錄密碼。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/01/install-google-chrome-ubuntu-5.jpeg?resize=800%2C516&amp;ssl=1" alt="在 Ubuntu 軟件中心中安裝 Google Chrome"></p><p>.deb 文件的安裝將通過軟件中心來執行。</p><p>看，它甚至比在 Windows 中安裝一個 .exe 文件更簡單，不是嗎？</p><h4 id="方法-2-使用-gdebi-應用程序來安裝-deb-軟件包及其依賴項" tabindex="-1">方法 2: 使用 Gdebi 應用程序來安裝 deb 軟件包及其依賴項 <a class="header-anchor" href="#方法-2-使用-gdebi-應用程序來安裝-deb-軟件包及其依賴項" aria-label="Permalink to “方法 2: 使用 Gdebi 應用程序來安裝 deb 軟件包及其依賴項”">​</a></h4><p>再提一次，如果事情總是進展順利，生活可能會更簡單一些。但是生活並不是我們熟知的那樣。</p><p>現在，你已經知道 .deb 文件可以簡單地通過軟件中心來安裝，接下來，讓我告訴你一些軟件包可能會遇到的依賴項的錯誤。</p><p>發生錯誤的原因是，一個程序可能依賴於另外一個軟件包（庫）。當開發者為你準備 DEB 軟件包時，他/她可能會假設你的系統中已經有了所依賴的軟件包（庫）。</p><p>但是如果情況並不是這樣的，你的系統沒有這些所需要的軟件包（庫），你將遇到臭名昭著的“依賴項錯誤”。</p>',18)),t("p",null,[s[7]||(s[7]=e("軟件中心不能處理這樣的錯誤，因此你不得不使用另外一個名稱為 ",-1)),n(i,{href:"https://itsfoss.com/gdebi-default-ubuntu-software-center/"},{default:l(()=>[...s[6]||(s[6]=[e("gdebi",-1)])]),_:1}),s[8]||(s[8]=e(" 的工具。",-1))]),s[43]||(s[43]=t("p",null,"gdebi 是一個輕量級的 GUI 應用程序，它只有安裝 deb 軟件包的一個用途。",-1)),s[44]||(s[44]=t("p",null,"它將識別依賴項，並嘗試在安裝 .deb 文件的同時安裝這些依賴項。",-1)),s[45]||(s[45]=t("p",null,[t("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/01/gdebi-handling-dependency.jpg?ssl=1",alt:"gdebi 在安裝 deb 軟件包時處理依賴項"})],-1)),t("p",null,[s[10]||(s[10]=e("就我個人而言，我更喜歡使用 gdebi 而不是使用軟件包中心來安裝 deb 文件。它是一個輕量級應用程序，因此安裝過程看起來更快一點。更多的信息，你可以閲讀",-1)),n(i,{href:"https://itsfoss.com/gdebi-default-ubuntu-software-center/"},{default:l(()=>[...s[9]||(s[9]=[e("使用 gDebi ，並使其成為安裝 DEB 軟件包的默認設置",-1)])]),_:1}),s[11]||(s[11]=e("。",-1))]),s[46]||(s[46]=a('<p>你可以從軟件中心或使用下面的命令來安裝 gdebi ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gdebi</span></span></code></pre></div><h4 id="方法-3-在命令列中使用-dpkg-安裝-deb-文件" tabindex="-1">方法 3: 在命令列中使用 dpkg 安裝 .deb 文件 <a class="header-anchor" href="#方法-3-在命令列中使用-dpkg-安裝-deb-文件" aria-label="Permalink to “方法 3: 在命令列中使用 dpkg 安裝 .deb 文件”">​</a></h4>',3)),t("p",null,[s[13]||(s[13]=e("如果你想在命令列中安裝 deb 軟件包，你可以使用 ",-1)),s[14]||(s[14]=t("code",null,"apt",-1)),s[15]||(s[15]=e(" 命令或者 ",-1)),s[16]||(s[16]=t("code",null,"dpkg",-1)),s[17]||(s[17]=e(" 命令。實際上，",-1)),s[18]||(s[18]=t("code",null,"apt",-1)),s[19]||(s[19]=e(" 命令在底層上使用 ",-1)),n(i,{href:"https://help.ubuntu.com/lts/serverguide/dpkg.html.en"},{default:l(()=>[...s[12]||(s[12]=[e("dpkg",-1)])]),_:1}),s[20]||(s[20]=e(" 命令，但是 ",-1)),s[21]||(s[21]=t("code",null,"apt",-1)),s[22]||(s[22]=e(" 卻更流行和易於使用。",-1))]),s[47]||(s[47]=a(`<p>如果你想對 deb 文件使用 <code>apt</code> 命令，像這樣使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install path_to_deb_file</span></span></code></pre></div><p>如果你想對將要安裝的 deb 軟件包使用 <code>dpkg</code> 命令，在這裏是如何完成它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg -i path_to_deb_file</span></span></code></pre></div><p>在這兩個命令中，你應該使用你已下載的 deb 文件的路徑和名稱來替換 <code>path_to_deb_file</code> 。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/02/install-deb-file-with-dpkg.png?ssl=1" alt="在 Ubuntu 中使用 dpkg 命令安裝 deb 文件"></p><p>如果你在安裝 deb 軟件包的過程中得到一個依賴項的錯誤，你可以使用下面的命令來修復依賴項的問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -f</span></span></code></pre></div><h3 id="如何移除-deb-軟件包" tabindex="-1">如何移除 deb 軟件包 <a class="header-anchor" href="#如何移除-deb-軟件包" aria-label="Permalink to “如何移除 deb 軟件包”">​</a></h3><p>移除一個 deb 軟件包也不是一件什麼大事。並且，你不需要用於安裝程序的原始的 deb 文件。</p><h4 id="方法-1-使用-apt-命令移除-deb-軟件包" tabindex="-1">方法 1: 使用 apt 命令移除 deb 軟件包 <a class="header-anchor" href="#方法-1-使用-apt-命令移除-deb-軟件包" aria-label="Permalink to “方法 1: 使用 apt 命令移除 deb 軟件包”">​</a></h4><p>你所需要的全部東西就是你所已安裝程序的名稱，接下來你可以使用 <code>apt</code> 或 <code>dpkg</code> 來移除這個程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove program_name</span></span></code></pre></div><p>現在，問題來了，在移除命令中，你如何找到你所需要使用的準確的程序名稱？為此，<code>apt</code> 命令也有一個解決方案。</p><p>你可以使用 <code>apt</code> 命令找到所有已安裝文件的列表，但是手動完成這一過程將會是一件令人頭疼的事。因此，你可以使用 <code>grep</code> 命令來搜索你的軟件包。</p><p>例如，在先前的部分中，我已安裝 AppGrid 應用程序，但是如果我想知道準確的程序名稱，我可以像這樣使用一些東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt list --installed | grep grid</span></span></code></pre></div><p>這將給予我全部的名稱中含有 “grid” 的軟件包，從這裏，我可以得到準確的程序名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --installed | grep grid</span></span>
<span class="line"><span>WARNING: apt does not have a stable CLI interface. Use with caution in scripts.</span></span>
<span class="line"><span>appgrid/now 0.298 all [installed,local]</span></span></code></pre></div><p>正如你所看到的，一個名稱為 “appgrid” 的軟件包已經安裝。現在，你可以在 <code>apt remove</code> 命令中使用這個程序名稱。</p><h4 id="方法2-使用-dpkg-命令移除-deb-軟件包" tabindex="-1">方法2: 使用 dpkg 命令移除 deb 軟件包 <a class="header-anchor" href="#方法2-使用-dpkg-命令移除-deb-軟件包" aria-label="Permalink to “方法2: 使用 dpkg 命令移除 deb 軟件包”">​</a></h4><p>你可以使用 <code>dpkg</code> 來找到已安裝程序的名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg -l | grep grid</span></span></code></pre></div><p>該輸出將給予所有的名稱中有 “grid” 的軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg -l | grep grid</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ii appgrid 0.298 all Discover and install apps for Ubuntu</span></span></code></pre></div><p>在上面的命令輸出中的 <code>ii</code> 意味着軟件包已經被正確地安裝。</p><p>現在，你有了程序名稱，你可以使用 <code>dpkg</code> 命令來移除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg -r program_name</span></span></code></pre></div><p><strong>提示：更新 deb 軟件包</strong></p><p>一些 deb 軟件包 （像 Chrome）通過系統更新來提供其更新，但是對於大多數的其它的程序，你將不得不先移除已存在的程序，並在接下來安裝更新的版本。</p><p>我希望這篇初學者指南能夠幫助你在 Ubuntu 上安裝 deb 軟件包。我添加了移除部分，以便你可以更好地控制你所安裝的程序。</p><hr>`,32)),t("p",null,[s[24]||(s[24]=e("via: ",-1)),n(i,{href:"https://itsfoss.com/install-deb-files-ubuntu"},{default:l(()=>[...s[23]||(s[23]=[e("https://itsfoss.com/install-deb-files-ubuntu",-1)])]),_:1})]),t("p",null,[s[29]||(s[29]=e("作者：",-1)),n(i,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...s[25]||(s[25]=[e("Abhishek Prakash",-1)])]),_:1}),s[30]||(s[30]=e(" 選題：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[26]||(s[26]=[e("lujun9972",-1)])]),_:1}),s[31]||(s[31]=e(" 譯者：",-1)),n(i,{href:"https://github.com/robsean"},{default:l(()=>[...s[27]||(s[27]=[e("robsean",-1)])]),_:1}),s[32]||(s[32]=e(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[28]||(s[28]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[35]||(s[35]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[33]||(s[33]=[e("LCTT",-1)])]),_:1}),s[36]||(s[36]=e(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...s[34]||(s[34]=[e("Linux中國",-1)])]),_:1}),s[37]||(s[37]=e(" 榮譽推出",-1))])])}const T=p(u,[["render",r]]);export{y as __pageData,T as default};
